use std::thread;

fn main() {
    let (work_tx, work_rx) = mpsc::channel::<i32>();
    let work_rx = std::sync::Arc::new(std::sync::Mutex::new(work_rx));
    let (result_tx, result_rx) = mpsc::channel::<i32>();

