fn counting_sort(arr) {
    let n = arr.length;
    if (n == 0) { return arr; }

    let max_val = arr[0];
    for (let i = 1; i < n; i++) {
        if (arr[i] > max_val) {
            max_val = arr[i];
        }
    }

    let count = [];
    for (let i = 0; i <= max_val; i++) {
        count.push(0);
