    let mut soa = SoA::new();
    let points = [(1.0, 0.0, 0.0), (0.0, 2.0, 0.0), (0.0, 0.0, 3.0), (1.0, 1.0, 1.0), (3.0, 4.0, 0.0)];
    unsafe {
        for (i, &(x, y, z)) in points.iter().enumerate() {
            soa.set_point(i, x, y, z);
