func mapWorker(chunk []int, resultCh chan<- []int, wg *sync.WaitGroup) {
	defer wg.Done()
	var results []int
	for _, v := range chunk {
		results = append(results, v*v)
	}
	resultCh <- results
}

func reduceWorker(values []int) int {
	sum := 0
	for _, v := range values {
		sum += v
	}
	return sum
