        println!("--- create object ---");
        let a = rc_new(42);
        println!("--- share with b ---");
        let b = rc_retain(a);
        println!("--- share with c ---");
        let c = rc_retain(a);
        println!("data: {}, refcount: {}", rc_get_data(a), rc_get_count(a));
        println!("--- release a ---");
        let _a = rc_release(a);
        println!("--- release b ---");
        let _b = rc_release(b);
        println!("--- release c (last ref, should free) ---");
