    for (int i = 0; i < total; i++) { g_score[i] = INF; f_score[i] = INF; came_from[i] = -1; }

    int sr = 0, sc = 0, er = 4, ec = 4;
    int start_key = sr * COLS + sc;
    g_score[start_key] = 0;
    f_score[start_key] = heuristic(sr, sc, er, ec);

