    heap: Vec<i32>,
}

impl MinHeap {
    fn new() -> Self { MinHeap { heap: vec![] } }

    fn insert(&mut self, val: i32) {
        self.heap.push(val);
        let mut i = self.heap.len() - 1;
        while i > 0 {
            let parent = (i - 1) / 2;
            if self.heap[i] < self.heap[parent] {
                self.heap.swap(i, parent);
                i = parent;
            } else {
                break;
            }
        }
    }

