for (let i = 0; i < 4; i++) {
    workers.push(spawn(worker, work_ch, result_ch));
}

// Wait for all workers to finish
for (let i = 0; i < 4; i++) {
    join(workers[i]);
}
result_ch.close();

// Collect results
let results = [];
loop {
    let val = result_ch.recv();
    if (val == null) {
        break;
    }
    results.push(val);
}

