fn bfs_shortest(adj: &Vec<Vec<usize>>, start: usize, end: usize, n: usize) -> (i32, Vec<usize>) {
    let mut visited = vec![false; n];
    let mut dist = vec![-1i32; n];
    let mut prev = vec![-1i64; n];
