                dist[v] = dist[u] + 1;
                prev[v] = u as i64;
                queue.push_back(v);
            }
        }
    }

    let mut path = Vec::new();
    let mut current = end as i64;
    while current != -1 {
        path.push(current as usize);
        current = prev[current as usize];
    }
    path.reverse();
    (dist[end], path)
}

