fn counting_sort_by_digit(arr: &mut Vec<i32>, exp: i32) {
    let n = arr.len();
    let mut output = vec![0i32; n];
    let mut count = vec![0usize; 10];

    for &x in arr.iter() {
        let digit = ((x / exp) % 10) as usize;
        count[digit] += 1;
