		"2 + 3",
		"10 * 4",
		"100 / 7",
		"50 - 18",
		"2 + 3 * 4",
	}

	fmt.Println("=== Simple Calculator ===")
	for _, input := range inputs {
		result := evaluate(input)
		intResult := int64(result)
		if float64(intResult) == result {
