function rodCutting(prices, n) {
    const dp = new Array(n + 1).fill(0);
    for (let i = 1; i <= n; i++) {
        for (let j = 1; j <= i; j++) {
            if (j < prices.length) {
                const candidate = prices[j] + dp[i - j];
                if (candidate > dp[i]) dp[i] = candidate;
