    pthread_t t;
    pthread_create(&t, NULL, merge_sort_thread, &sa);
    pthread_join(t, NULL);

    printf("sorted:");
    for (int i = 0; i < n; i++) printf(" %d", arr[i]);
    printf("\n");
    return 0;
