import { divi } from "@stdlib/math";

fn make_pq() {
    return { heap: [] };
}

fn pq_swap(heap, i, j) {
    let tmp = heap[i];
    heap[i] = heap[j];
    heap[j] = tmp;
}

fn pq_insert(pq, val) {
    pq.heap.push(val);
    let i = pq.heap.length - 1;
    while (i > 0) {
        let parent = divi(i - 1, 2);
        if (pq.heap[i] < pq.heap[parent]) {
            pq_swap(pq.heap, i, parent);
            i = parent;
        } else {
