// In Hemlock, bitwise operators are identical to C: &, |, ^, ~, <<, >>
// The main difference is no pass-by-pointer — functions return new values.

fn set_bit(n, pos) {
    return n | (1 << pos);
}

fn clear_bit(n, pos) {
    return n & ~(1 << pos);
}

fn toggle_bit(n, pos) {
    return n ^ (1 << pos);
}

fn check_bit(n, pos) {
    return (n >> pos) & 1;
}

fn count_bits(n) {
    let count = 0;
    let val = n;
    while (val != 0) {
        count = count + (val & 1);
        val = val >> 1;
    }
    return count;
}

