struct Queue {
    inbox: Vec<i32>,
    outbox: Vec<i32>,
}

impl Queue {
    fn new() -> Self { Queue { inbox: vec![], outbox: vec![] } }
    fn enqueue(&mut self, val: i32) { self.inbox.push(val); }
    fn dequeue(&mut self) -> Option<i32> {
        if self.outbox.is_empty() {
            while let Some(x) = self.inbox.pop() {
                self.outbox.push(x);
            }
        }
        self.outbox.pop()
    }
}

