// Object layout: int refcount + int data
typedef struct { int refcount; int data; } Obj;

Obj *rc_new(int data) {
    Obj *obj = malloc(sizeof(Obj));
    obj->refcount = 1; obj->data = data;
    printf("created obj(data=%d, refcount=1)\n", data);
    return obj;
