    if (obj->refcount == 0) {
        printf("release obj(data=%d, refcount=0) -> freed\n", obj->data);
        free(obj);
        return NULL;
    }
    printf("release obj(data=%d, refcount=%d)\n", obj->data, obj->refcount);
    return obj;
}

