// Searches a sorted array for a target value using iterative bisection.

fn binary_search(arr, target) {
    let low = 0;
    let high = arr.length - 1;

    while (low <= high) {
        let mid = low + divi(high - low, 2);
        if (arr[mid] == target) {
            return mid;
        } else if (arr[mid] < target) {
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    return null;
}

