    let mut root: Tree = None;
    for &v in &[50, 30, 70, 20, 40, 60, 80] {
        root = insert(root, v);
    }
    let result = levelorder(&root);
    let s: Vec<String> = result.iter().map(|x| x.to_string()).collect();
    println!("levelorder: {}", s.join(" "));
