    Node *x = y->left, *t2 = x->right;
    x->right = y; y->left = t2;
    y->height = max_val(height(y->left), height(y->right)) + 1;
    x->height = max_val(height(x->left), height(x->right)) + 1;
    return x;
}

Node *left_rotate(Node *x) {
    Node *y = x->right, *t2 = y->left;
    y->left = x; x->right = t2;
    x->height = max_val(height(x->left), height(x->right)) + 1;
    y->height = max_val(height(y->left), height(y->right)) + 1;
    return y;
}

Node *insert(Node *root, int value) {
