// Union-Find data structures
let uf_parent = [];
let uf_rank = [];

fn uf_init(n) {
    for (let i = 0; i < n; i++) {
        uf_parent.push(i);
        uf_rank.push(0);
    }
}

fn uf_find(x) {
    while (uf_parent[x] != x) {
        uf_parent[x] = uf_parent[uf_parent[x]];
        x = uf_parent[x];
    }
    return x;
}

fn uf_union(a, b) {
    let ra = uf_find(a);
    let rb = uf_find(b);
    if (ra == rb) { return false; }
    if (uf_rank[ra] < uf_rank[rb]) {
        uf_parent[ra] = rb;
    } else if (uf_rank[ra] > uf_rank[rb]) {
        uf_parent[rb] = ra;
    } else {
        uf_parent[rb] = ra;
        uf_rank[ra] = uf_rank[ra] + 1;
    }
