// BFS Shortest Path (Unweighted)
// Finds shortest path in an unweighted graph using breadth-first search.

fn bfs_shortest(adj, start, end, n) {
    let visited = [];
    let dist = [];
    let prev = [];
    for (let i = 0; i < n; i++) {
        visited.push(false);
        dist.push(-1);
        prev.push(-1);
    }

    let queue = [];
    queue.push(start);
    visited[start] = true;
    dist[start] = 0;

    while (queue.length > 0) {
        let u = queue.shift();
        if (u == end) { break; }
        for (v in adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                dist[v] = dist[u] + 1;
                prev[v] = u;
                queue.push(v);
            }
        }
    }

    // Reconstruct path
    let path = [];
    let current = end;
    while (current != -1) {
        path.unshift(current);
        current = prev[current];
    }

    return { distance: dist[end], path: path };
}

