import (
	"fmt"
	"sync"
)

func philosopher(id int, forks []chan int, numPhil int, resultsCh chan<- int, wg *sync.WaitGroup) {
	defer wg.Done()

	left := id
	right := (id + 1) % numPhil

	first, second := left, right
	if left > right {
		first, second = right, left
	}

	// Pick up forks in order
	<-forks[first]
	<-forks[second]

	// Eat
	fmt.Printf("philosopher %d is eating\n", id)

