    // Put down forks
    forks[first].send(1);
    forks[second].send(1);

    results_ch.send(id);
}

let tasks = [];
for (let i = 0; i < num_phil; i++) {
    tasks.push(spawn(philosopher, i, forks, num_phil, results_ch));
}

for (let i = 0; i < num_phil; i++) {
    join(tasks[i]);
}

for (let i = 0; i < num_phil; i++) {
    results_ch.recv();
}
results_ch.close();

// Close fork channels
for (let i = 0; i < num_phil; i++) {
    // Drain remaining token
    forks[i].recv();
    forks[i].close();
}

