    }
    dq_size++;
    print(`push_front: ${val}`);
}

fn push_back(val: i32) {
    let node = make_node(val);
    if (dq_tail == null) {
        dq_head = node;
        dq_tail = node;
    } else {
        set_prev(node, dq_tail);
        set_next(dq_tail, node);
        dq_tail = node;
    }
    dq_size++;
    print(`push_back: ${val}`);
}

fn pop_front() {
    if (dq_head == null) {
        print("deque empty");
        return null;
    }
    let node = dq_head;
    let val = node_val(node);
    let nxt = get_next(node);
    if (nxt != null) {
        set_prev(nxt, null);
    } else {
        dq_tail = null;
    }
    dq_head = nxt;
    free(node);
    dq_size--;
    print(`pop_front: ${val}`);
    return val;
}

fn pop_back() {
    if (dq_tail == null) {
        print("deque empty");
        return null;
    }
    let node = dq_tail;
    let val = node_val(node);
    let prv = get_prev(node);
    if (prv != null) {
        set_next(prv, null);
    } else {
        dq_head = null;
    }
    dq_tail = prv;
    free(node);
    dq_size--;
    print(`pop_back: ${val}`);
    return val;
}

fn print_deque() {
    write("deque:");
    let cur = dq_head;
    while (cur != null) {
        write(` ${node_val(cur)}`);
        cur = get_next(cur);
    }
    print("");
}

