fn topological_sort(adj: &Vec<Vec<usize>>, n: usize) -> Vec<usize> {
    let mut in_degree = vec![0usize; n];
    for u in 0..n {
        for &v in &adj[u] {
            in_degree[v] += 1;
        }
    }
    let mut queue = VecDeque::new();
    for i in 0..n {
