fn quicksort(arr: &mut Vec<i32>, low: usize, high: usize) {
    if low < high {
        let pivot = arr[high];
        let mut i = low as i64 - 1;
        for j in low..high {
            if arr[j] <= pivot {
                i += 1;
                arr.swap(i as usize, j);
            }
        }
        let pi = (i + 1) as usize;
        arr.swap(pi, high);
        if pi > 0 {
            quicksort(arr, low, pi - 1);
        }
        quicksort(arr, pi + 1, high);
    }
}

